1	import { hashState } from "../hash.js";
2	import {
3	  requireId,
4	  requireInteger,
5	  type ClaimEndReport,
6	  type MatchConfig,
7	  type MatchEnd,
8	  type MatchEvent,
9	  type MatchInput,
10	  type MatchPhase,
11	  type MatchPlayer,
12	  type MatchPlayerResult,
13	  type MatchPlayerStats,
14	  type MatchReport,
15	  type MatchResults,
16	  type MatchState,
17	  type MatchStatEvent,
18	  type MatchStepResult,
19	} from "./state.js";
