1	import { afterAll, beforeAll, describe, expect, it } from "vitest";
2	import { claimRules } from "@pirate-sea-race/content/claim";
3	import { TEST_NEXT_MATCH_TIMINGS_PATH } from "@pirate-sea-race/protocol";
4	import { startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
5	import { HeadlessClient, type ResultLineView } from "@pirate-sea-race/test-tools";
6	import type { MatchReport } from "@pirate-sea-race/simulation/match";
7	import { GUEST_SEAT, HOST_SEAT } from "./rubbingsSetup.js";
8	import { flowTuning } from "./matchFlowSetup.js";
9	import { playersAt, roomOf, tracker, until } from "./seaDuelSetup.js";
10	
11	/**
12	 * The room's reports to the match flow through the real room (§2): a report naming a player the flow does not know is
13	 * dropped before `stepMatch` (which throws on one) while the known players' reports still count; and the test-only
14	 * timings for the next match created. Test-only timings: a two-second channel and a 10 s match.
15	 */
16	const MATCH_TICKS = 200;
17	let server: RunningGameServer;
18	let endpoint: string;
19	
20	beforeAll(async () => {
21	  const matchTuning = flowTuning({ claim: { ...claimRules, channelTicks: 40, deadlineTicks: MATCH_TICKS } });
22	  server = await startGameServer({ port: 0, host: "127.0.0.1", handleSignals: false, testPlacement: true, matchTuning });
23	  endpoint = `http://127.0.0.1:${server.port}`;
24	});
25	
26	afterAll(async () => {
27	  await server.close();
28	});
29	
30	const line = (seat: number, change: Partial<ResultLineView> = {}): ResultLineView => ({
31	  seat,
32	  winner: false,
33	  left: false,
34	  rubbingsHeld: 0,
35	  collected: 0,
36	  thefts: 0,
37	  lost: 0,
38	  duelsWon: 0,
39	  duelsLost: 0,
40	  duelsDrawn: 0,
41	  gold: 50,
42	  cachesClaimed: 0,
43	  islandsVisited: 0,
44	  ...change,
45	});
46	
47	function postTimings(body: unknown): Promise<Response> {
48	  return fetch(`${endpoint}${TEST_NEXT_MATCH_TIMINGS_PATH}`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
49	}
50	
51	// One after another: the posted timings go to whichever match is created next.
52	describe("the room's reports to the match flow (§2)", () => {
53	  it("drops a report naming a ghost player without throwing, and still counts the known players' reports of the same tick", async ({ onTestFinished }) => {
54	    const track = tracker(onTestFinished);
55	    const [host, guest] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT], track)) as [HeadlessClient, HeadlessClient];
56	    const room = roomOf(host);
57	    // The clock stops after a tick in play; the reports go in meanwhile, so the next tick's flow step takes them all.
58	    const stopAt = room.matchState.worldTick + 2;
59	    room.pauseAfterTick(stopAt);
60	    await until(() => room.worldPaused, 5000, "the pause");
61	    const ghosts: MatchReport[] = [
62	      { kind: "collected", playerId: "ghost" },
63	      { kind: "stole", playerId: "ghost" },
64	      { kind: "lost", playerId: "ghost" },
65	      { kind: "cache-claimed", playerId: "ghost" },
66	      { kind: "gold", playerId: "ghost", gold: 99 },
67	      { kind: "island-visited", playerId: "ghost", island: "3" },
68	      { kind: "duel-ended", playerIds: ["ghost", guest.sessionId], winner: "ghost" },
69	      // A claim won by a ghost on the very tick the flow steps: it would end the match with an unknown winner.
70	      { kind: "match-ended", tick: stopAt + 1, reason: "claim", winner: "ghost" },
71	    ];
72	    const known: MatchReport[] = [
