1386	+/**
1387	+ * The match flow's configs (§2, §5), built from one set of rules so they cannot disagree: the match module's timer
1388	+ * runs for exactly the claim rules' `deadlineTicks` (the claim deadline and the 35:00 timer are one number), its
1389	+ * departure lasts exactly the encounter rules' spawn protection, and its starting gold is the ledger's.
1390	+ */
1391	+export interface FlowRules {
1392	+  /** §2's lobby and ready check. `departureTicks` is ignored: the departure is the encounter rules' spawn protection. */
1393	+  readonly match: MatchRules;
1394	+  /** §5's channel, circle and §2's deadline. */
1395	+  readonly claim: ClaimRules;
1396	+  /** §2's minute-20 and minute-28 reveals. */
1397	+  readonly intel: IntelRules;
1398	+  readonly encounters: EncounterRules;
1399	+  readonly objectives: ObjectiveRules;
1400	+}
1401	+
1402	+/**
1403	+ * The lobby-to-results config of a private match. The private minimum is the match module's (`PRIVATE_MIN_PLAYERS`,
1404	+ * 2): the content's older `privateMatch.minPlayers` (1) is stale and not read.
1405	+ */
1406	+export function matchConfigFor(rules: FlowRules): MatchConfig {
1407	+  return createMatchConfig({
1408	+    kind: "private",
1409	+    rules: { ...rules.match, departureTicks: rules.encounters.spawnProtectionTicks },
1410	+    durationTicks: rules.claim.deadlineTicks,
1411	+    startingGold: rules.objectives.startingGold,
1412	+  });
1413	+}
1414	+
1415	+/** The claim config once player control starts on `controlStartTick`: its deadline is the timer's end. */
1416	+export function claimConfigFor(rules: FlowRules, claimPoint: ClaimPoint, controlStartTick: number, map: SeaMapDefinition): ClaimConfig {
1417	+  return createClaimConfig({ claimPoint, controlStartTick, rules: rules.claim, subUnitsPerTile: map.subUnitsPerTile });
1418	+}
1419	+
1420	+/** The intel config once player control starts: the reveals count from `controlStartTick`. */
1421	+export function intelConfigFor(rules: FlowRules, claimPoint: ClaimPoint, controlStartTick: number, map: SeaMapDefinition): IntelConfig {
1422	+  return createIntelConfig({ preset: MATCH_PRESET, finalIsland: claimPoint, controlStartTick, map, rules: rules.intel });
1423	+}
1424	+
1425	+/** The final island (§3, §5): the socket a secret picks, and its claim point, the centre of its claim tile. */
1426	+export function finalIslandOf(map: SeaMapDefinition, secret: number): { readonly socket: number; readonly claimPoint: ClaimPoint } {
1427	+  const socket = chooseFinalSocket(map, secret);
1428	+  const tile = map.finalSockets[socket]!.claimTile;
1429	+  const half = Math.floor(map.subUnitsPerTile / 2);
1430	+  return { socket, claimPoint: { x: tile.tileX * map.subUnitsPerTile + half, y: tile.tileY * map.subUnitsPerTile + half } };
