1502	--- /dev/null
1503	+++ b/apps/server/src/matchSeeds.ts
1504	@@ -0,0 +1,33 @@
1505	+import { createHmac, randomBytes } from "node:crypto";
1506	+
1507	+/**
1508	+ * A match's seeds (§3, §16). The room draws one private master secret per match from `node:crypto` and derives an
1509	+ * independent 32-bit seed for each system from it with a keyed hash: HMAC-SHA-256 keyed by the secret over
1510	+ * `SEED_LABEL` and the system's name, of which the first four bytes (big-endian) are the seed. So no system's seed
1511	+ * says anything about another's, none is ever passed raw to two systems, and none depends on the public match code,
1512	+ * which the derivation never reads.
1513	+ */
1514	+
1515	+/** Bytes in a master secret: 256 bits. */
1516	+export const MASTER_SECRET_BYTES = 32;
1517	+
1518	+/** The versioned label every derivation hashes before the system's name. */
1519	+export const SEED_LABEL = "pirate-sea-race/seed/v1/";
1520	+
1521	+/**
1522	+ * The systems that draw a seed. `world` seeds the simulation state, `ledger` the rubbings' deal onto the sources,
1523	+ * `final-socket` the final island's socket, `intel` the intel module's draws; `ruins` and `fruit` are reserved for the
1524	+ * ruins' puzzles and the fruit deal. Each duel at sea draws `duel:<n>`, its n-th duel.
1525	+ */
1526	+export type SeedSystem = "world" | "ledger" | "final-socket" | "intel" | "ruins" | "fruit" | `duel:${number}`;
1527	+
1528	+/** A fresh master secret from `node:crypto`: the production source. */
1529	+export function drawMasterSecret(): Uint8Array {
1530	+  return new Uint8Array(randomBytes(MASTER_SECRET_BYTES));
1531	+}
1532	+
1533	+/** The seed of one system: HMAC-SHA-256(secret, SEED_LABEL + system), its first four bytes as an unsigned integer. */
1534	+export function deriveSeed(secret: Uint8Array, system: SeedSystem): number {
1535	+  if (secret.length < 16) throw new RangeError(`a master secret needs at least 16 bytes, got ${secret.length}`);
1536	+  return createHmac("sha256", secret).update(SEED_LABEL + system, "utf8").digest().readUInt32BE(0);
1537	+}
