375	}
376	
377	/** The flow's part of the page (§2, §5): the lobby, the clock bar, the compass, the claim panel and the results screen. */
378	export function flowView(model: FlowModel): FlowView {
379	  const { lobby } = model;
380	  const inLobby = lobby.phase === "lobby" || lobby.phase === "ready";
381	  const playing = lobby.phase === "departure" || lobby.phase === "exploration";
382	  const shown = lobbyModel(lobby);
383	  const route = routeLine(model.claim, model.own, model.subUnitsPerTile);
384	  const claim = claimLines(model.claim, {
385	    inCircle: insideCircle(model.claim, model.own, model.treasureRadius),
386	    speed: model.own?.speed ?? 0,
387	    worldTick: lobby.worldTick,
388	    phase: lobby.phase,
389	    rivalClaiming: model.rivalClaiming,
390	  });
391	  const results = resultsModel(model.results);
392	  return {
393	    phase: { text: phaseText(lobby.phase), state: lobby.phase },
394	    timer: timerLine({ phase: lobby.phase, remainingTicks: model.remainingTicks }),
395	    remaining: String(model.remainingTicks),
396	    sector: model.finalSector === "" ? "" : `Treasure sector: ${model.finalSector}`,
397	    lobby: {
398	      hidden: !inLobby,
399	      purseHidden: inLobby,
400	      code: model.code,
401	      players: shown.players,
402	      startHidden: !shown.showStart,
403	      startDisabled: !shown.canStart,
404	      hint: lobby.phase === "ready" ? { text: shown.hint, state: lobby.phase, seconds: secondsUntil(lobby.readyEndsAt, lobby.worldTick) } : { text: shown.hint, state: lobby.phase },
405	    },
406	    route,
407	    compass: {
408	      hidden: !playing,
409	      state: route.state,
410	      active: route.state === "active",
411	      bearing: route.bearing ?? 0,
412	      distance: route.distanceTiles === undefined ? undefined : String(route.distanceTiles),
413	      text: route.state === "none" ? NO_ROUTE_TEXT : route.text,
414	    },
415	    claim: {
416	      panelHidden: claim.claim.state === "none",
417	      text: claim.claim,
418	      risk: claim.risk,
419	      progressHidden: claim.claim.state !== "channel",
420	      progress: claim.progress,
421	      held: String(model.claim?.claimHeld ?? 0),
422	      total: String(model.claim?.claimTotal ?? 0),
423	    },
424	    results: {
425	      hidden: results === undefined,
426	      reason: model.results.endReason,
427	      winnerSeat: String(model.results.winnerSeat),
428	      headline: results?.headline ?? "",
429	      detail: results?.detail ?? "",
430	      rows: (results?.rows ?? []).map((row) => ({
431	        seat: String(row.seat),
432	        winner: String(row.winner),
433	        cells: [row.winner ? `${row.label} 🏆` : row.label, ...row.cells.map(String)],
434	      })),
435	    },
436	  };
437	}
438	
439	/** A player's own status as the flow reads it from the synced state (any field may be missing before the first patch). */
440	export interface FlowStatusSnapshot {
441	  readonly seat?: number;
442	  readonly fullSet?: boolean;
443	  readonly routeKnown?: boolean;
444	  readonly routeActive?: boolean;
445	  readonly routeX?: number;
446	  readonly routeY?: number;
447	  readonly claim?: string;
448	  readonly claimHeld?: number;
449	  readonly claimTotal?: number;
450	  readonly claimInterrupt?: string;
451	  readonly claimInterruptAt?: number;
452	}
453	
454	/** The synced state as the flow reads it: public fields, the ships in view, and this player's own status (§16). */
455	export interface FlowSnapshot {
456	  readonly code: string;
457	  readonly worldTick: number;
458	  readonly phase?: string;
459	  readonly hostSeat?: number;
460	  readonly minPlayers?: number;
461	  readonly readyEndsAt?: number;
462	  readonly remainingTicks?: number;
463	  readonly finalSector?: string;
464	  readonly treasureRadius?: number;
465	  readonly endReason?: string;
466	  readonly winnerSeat?: number;
467	  readonly roster?: { values(): Iterable<{ readonly seat: number }> };
468	  readonly results?: Iterable<ResultsState["lines"][number]>;
469	  readonly status?: { get(id: string): FlowStatusSnapshot | undefined };
470	  readonly ships?: { values(): Iterable<{ readonly id: string; readonly x: number; readonly y: number; readonly speed: number; readonly claiming?: boolean; readonly claimHeld?: number }> };
471	}
472	
473	/** The ships in view channelling the claim (§5: nearby players are warned), with the ticks each has held. */
474	export function claimingShipsOf(state: FlowSnapshot): Map<string, number> {
475	  const claiming = new Map<string, number>();
476	  for (const ship of state.ships?.values() ?? []) if (ship.claiming === true) claiming.set(ship.id, ship.claimHeld ?? 0);
477	  return claiming;
478	}
479	
480	/** The flow's model from the synced state (public) and this player's own status (private, §16). */
481	export function flowModelOf(state: FlowSnapshot, selfId: string, subUnitsPerTile: number): FlowModel {
482	  const status = state.status?.get(selfId);
483	  const own = [...(state.ships?.values() ?? [])].find((ship) => ship.id === selfId);
484	  const claim: ClaimStatus | undefined =
485	    status === undefined
486	      ? undefined
487	      : {
488	          fullSet: status.fullSet === true,
489	          routeKnown: status.routeKnown === true,
490	          routeActive: status.routeActive === true,
491	          routeX: status.routeX ?? 0,
492	          routeY: status.routeY ?? 0,
493	          claim: status.claim ?? "",
494	          claimHeld: status.claimHeld ?? 0,
495	          claimTotal: status.claimTotal ?? 0,
496	          claimInterrupt: status.claimInterrupt ?? "",
497	          claimInterruptAt: status.claimInterruptAt ?? 0,
498	        };
499	  return {
500	    code: state.code,
501	    rivalClaiming: [...claimingShipsOf(state).keys()].some((id) => id !== selfId),
502	    lobby: {
503	      phase: state.phase ?? "",
504	      seats: [...(state.roster?.values() ?? [])].map((entry) => entry.seat),
505	      hostSeat: state.hostSeat ?? 0,
506	      seat: status?.seat ?? 0,
507	      minPlayers: state.minPlayers ?? 2,
508	      readyEndsAt: state.readyEndsAt ?? 0,
509	      worldTick: state.worldTick,
510	    },
511	    remainingTicks: state.remainingTicks ?? 0,
512	    finalSector: state.finalSector ?? "",
513	    claim,
514	    own: own === undefined ? undefined : { x: own.x, y: own.y, speed: own.speed },
515	    treasureRadius: state.treasureRadius ?? 0,
516	    subUnitsPerTile,
517	    results: {
518	      endReason: state.endReason ?? "",
519	      winnerSeat: state.winnerSeat ?? 0,
520	      seat: status?.seat ?? 0,
521	      hostSeat: state.hostSeat ?? 0,
522	      lines: [...(state.results ?? [])],
523	    },
524	  };
525	}
