527	function field(root: ParentNode, id: string): HTMLElement {
528	  const element = root.querySelector<HTMLElement>(`[data-testid="${id}"]`);
529	  if (element === null) throw new Error(`missing flow field ${id}`);
530	  return element;
531	}
532	
533	/** Sets a data attribute, or removes it for undefined. */
534	function data(element: HTMLElement, name: string, value: string | undefined): void {
535	  if (value === undefined) delete element.dataset[name];
536	  else element.dataset[name] = value;
537	}
538	
539	function write(element: HTMLElement, line: HudLine): void {
540	  element.textContent = line.text;
541	  element.dataset["state"] = line.state;
542	  data(element, "seconds", line.seconds === undefined ? undefined : String(line.seconds));
543	}
544	
545	/** Rebuilds an element's children only when their content changed (`key`), so a list is not redrawn every frame. */
546	function rebuild(element: HTMLElement, key: string, children: () => Node[]): void {
547	  if (element.dataset["built"] === key) return;
548	  element.dataset["built"] = key;
549	  element.replaceChildren(...children());
550	}
551	
552	function cell(tag: "th" | "td", text: string): HTMLTableCellElement {
553	  const element = document.createElement(tag);
554	  element.textContent = text;
555	  return element;
556	}
557	
558	/** Writes the flow's view into the page: every decision is `flowView`'s, this only copies it. */
559	export function renderFlow(root: ParentNode, model: FlowModel): void {
560	  applyFlow(root, flowView(model));
561	}
562	
563	export function applyFlow(root: ParentNode, view: FlowView): void {
564	  write(field(root, "flow-phase"), view.phase);
565	  const timer = field(root, "match-timer");
566	  write(timer, view.timer);
567	  timer.dataset["remaining"] = view.remaining;
568	  field(root, "flow-sector").textContent = view.sector;
569	
570	  field(root, "lobby").hidden = view.lobby.hidden;
571	  root.querySelectorAll<HTMLElement>("#purse").forEach((purse) => (purse.hidden = view.lobby.purseHidden));
572	  field(root, "lobby-code").textContent = view.lobby.code;
573	  const list = field(root, "lobby-players");
574	  list.dataset["players"] = view.lobby.players.map((player) => player.label).join("|");
575	  rebuild(list, list.dataset["players"], () =>
576	    view.lobby.players.map((player) => {
577	      const item = document.createElement("li");
578	      item.dataset["seat"] = String(player.seat);
579	      item.textContent = player.label;
580	      return item;
581	    }),
582	  );
583	  const start = field(root, "start-match") as HTMLButtonElement;
584	  start.hidden = view.lobby.startHidden;
585	  start.disabled = view.lobby.startDisabled;
586	  write(field(root, "lobby-hint"), view.lobby.hint);
587	
588	  write(field(root, "hud-route"), view.route);
589	  const compass = field(root, "compass");
590	  compass.hidden = view.compass.hidden;
591	  compass.dataset["state"] = view.compass.state;
592	  compass.dataset["active"] = String(view.compass.active);
593	  compass.style.setProperty("--bearing", `${view.compass.bearing}rad`);
594	  data(compass, "distance", view.compass.distance);
595	  field(root, "compass-text").textContent = view.compass.text;
596	
597	  field(root, "claim-panel").hidden = view.claim.panelHidden;
598	  write(field(root, "claim-text"), view.claim.text);
599	  write(field(root, "claim-risk"), view.claim.risk);
600	  const bar = field(root, "claim-progress");
601	  bar.hidden = view.claim.progressHidden;
602	  bar.style.setProperty("--progress", String(view.claim.progress));
603	  bar.dataset["held"] = view.claim.held;
604	  bar.dataset["total"] = view.claim.total;
605	
606	  const screen = field(root, "results");
607	  screen.hidden = view.results.hidden;
608	  screen.dataset["reason"] = view.results.reason;
609	  screen.dataset["winnerSeat"] = view.results.winnerSeat;
610	  field(root, "results-headline").textContent = view.results.headline;
611	  field(root, "results-detail").textContent = view.results.detail;
612	  const table = field(root, "results-table");
613	  table.dataset["rows"] = JSON.stringify(view.results.rows);
614	  rebuild(table.querySelector("thead")!, "head", () => [headRow()]);
615	  rebuild(table.querySelector("tbody")!, table.dataset["rows"], () =>
616	    view.results.rows.map((row) => {
617	      const line = document.createElement("tr");
618	      line.dataset["seat"] = row.seat;
619	      line.dataset["winner"] = row.winner;
620	      line.append(...row.cells.map((value) => cell("td", value)));
621	      return line;
622	    }),
623	  );
624	}
625	
626	function headRow(): HTMLTableRowElement {
627	  const head = document.createElement("tr");
628	  for (const title of ["Player", ...RESULT_COLUMNS]) {
629	    const header = cell("th", title);
630	    header.scope = "col";
631	    head.append(header);
632	  }
633	  return head;
634	}
635	
636	/** How long a reveal's banner stays up. */
637	export const BANNER_MS = 7000;
638	
639	/** Shows a reveal's banner over the sea for a while, and adds it to the page's list of reveals. */
640	export function showBanner(root: ParentNode, banner: Banner, timers: { hide?: number }): void {
641	  const element = field(root, "banner");
642	  element.hidden = false;
643	  element.dataset["kind"] = banner.kind;
644	  element.dataset["tone"] = banner.tone;
645	  field(root, "banner-title").textContent = banner.title;
646	  field(root, "banner-detail").textContent = banner.detail;
647	  if (timers.hide !== undefined) window.clearTimeout(timers.hide);
648	  timers.hide = window.setTimeout(() => {
649	    element.hidden = true;
650	  }, BANNER_MS);
651	  const entry = document.createElement("li");
652	  entry.dataset["kind"] = banner.kind;
653	  entry.textContent = `${banner.title} ${banner.detail}`;
654	  field(root, "reveal-log").append(entry);
655	}
