1	import { expect, type APIRequestContext, type Browser, type BrowserContext, type Page, type TestInfo } from "@playwright/test";
2	import { HEADING_COUNT, isNavigable, seaMap, shipTuning, SUB_UNITS_PER_TILE, TILE_PIXELS, WORLD_STEPS_PER_SECOND } from "../../packages/content/src/index.js";
3	import { TEST_NEXT_MATCH_TIMINGS_PATH, TEST_PLACEMENT_PATH, type TestTimings } from "../../packages/protocol/src/index.js";
4	
5	export const SERVER_URL = "http://localhost:2593";
6	export const TILE = SUB_UNITS_PER_TILE;
7	const PIXELS_PER_SUB_UNIT = TILE_PIXELS / SUB_UNITS_PER_TILE;
8	
9	export interface Readout {
10	  readonly id: string;
11	  readonly slot: number;
12	  readonly x: number;
13	  readonly y: number;
14	  readonly heading: number;
15	  readonly speed: number;
16	  readonly dock: number;
17	}
18	
19	export interface DrawnShip {
20	  readonly id: string;
21	  readonly x: number;
22	  readonly y: number;
23	  readonly color: string;
24	}
25	
26	export async function createMatch(page: Page): Promise<string> {
27	  await page.goto("/");
28	  await page.getByRole("button", { name: "Create match" }).click();
29	  await expect(page.getByTestId("hud-status")).toHaveText("connected");
30	  const code = page.getByTestId("hud-code");
31	  await expect(code).toHaveText(/^[A-Z0-9]{6}$/);
32	  return (await code.textContent())!;
33	}
34	
35	export async function joinMatch(page: Page, code: string): Promise<void> {
36	  await page.goto("/");
37	  await page.getByLabel("Match code").fill(code);
38	  await page.getByRole("button", { name: "Join", exact: true }).click();
39	  await expect(page.getByTestId("hud-status")).toHaveText("connected");
40	}
41	
42	/**
43	 * The pinned final-socket secret of the browser server (`PIRATE_SEA_RACE_TEST_FINAL_SECRET` in the Playwright config),
44	 * so a scenario knows where the final island is.
45	 */
46	export const FINAL_SECRET = 3;
47	
48	/**
49	 * Starts a match through its lobby, as players do (§2): the host clicks Start, every page shows the ready countdown,
50	 * then the running timer once control starts; the departure's short protection (test-only, 1 s) runs out.
51	 */
52	export async function startMatch(host: Page, ...others: Page[]): Promise<void> {
53	  const start = host.getByRole("button", { name: "Start match" });
54	  await expect(start).toBeEnabled();
55	  await start.click();
56	  for (const page of [host, ...others]) {
57	    await expect(page.getByTestId("match-timer")).toHaveAttribute("data-state", "running", { timeout: 15_000 });
58	    await expect(page.getByTestId("lobby")).toBeHidden();
59	  }
60	  for (const page of [host, ...others]) await expect(page.getByTestId("hud-protection")).toHaveAttribute("data-state", "none", { timeout: 5000 });
61	}
62	
63	/**
64	 * A lone player's match needs a second player to start (§2: private matches start with two). A companion joins from
65	 * its own browser context and stays at its spawn slot; the host starts. Close the returned context when done.
66	 */
67	export async function startWithCompanion(browser: Browser, host: Page, code: string): Promise<BrowserContext> {
68	  const context = await browser.newContext();
69	  const companion = await context.newPage();
70	  await joinMatch(companion, code);
71	  await expect(host.getByTestId("hud-players")).toHaveText("2");
72	  await startMatch(host, companion);
73	  return context;
74	}
75	
76	export async function selfId(page: Page): Promise<string> {
77	  return (await page.getByTestId("hud-self").textContent())!;
78	}
79	
80	/** Every ship the page's HUD lists, with the latest decoded server state. */
81	export async function listed(page: Page): Promise<Readout[]> {
82	  return page.evaluate(() =>
83	    [...document.querySelectorAll<HTMLElement>('[data-testid="positions"] [data-ship-id]')].map((item) => ({
84	      id: item.dataset["shipId"]!,
85	      slot: Number(item.dataset["slot"]),
86	      x: Number(item.dataset["x"]),
87	      y: Number(item.dataset["y"]),
88	      heading: Number(item.dataset["heading"]),
89	      speed: Number(item.dataset["speed"]),
90	      dock: Number(item.dataset["dock"]),
91	    })),
92	  );
93	}
94	
95	export async function listedIds(page: Page): Promise<string[]> {
96	  return (await listed(page)).map((ship) => ship.id).sort();
97	}
98	
99	/** A ship's authoritative state in a page's HUD, or undefined when the page does not list it. */
100	export async function readout(page: Page, shipId: string): Promise<Readout | undefined> {
101	  return (await listed(page)).find((ship) => ship.id === shipId);
102	}
103	
104	export async function drawnShips(page: Page): Promise<DrawnShip[]> {
105	  return JSON.parse((await page.getByTestId("game").getAttribute("data-drawn-ships")) ?? "[]") as DrawnShip[];
106	}
107	
108	export async function drawnIds(page: Page): Promise<string[]> {
109	  return (await drawnShips(page)).map((ship) => ship.id).sort();
110	}
111	
112	/**
113	 * Test-only placement (the server's PIRATE_SEA_RACE_TEST_PLACEMENT setting, on for these tests): puts a player's
114	 * ship at rest on a tile, then waits until the page shows it there.
115	 */
116	export async function place(request: APIRequestContext, page: Page, code: string, tileX: number, tileY: number, heading: number): Promise<void> {
117	  const sessionId = await selfId(page);
118	  const response = await request.post(`${SERVER_URL}${TEST_PLACEMENT_PATH}`, { data: { code, sessionId, tileX, tileY, heading } });
119	  expect(response.status(), await response.text()).toBe(200);
120	  await expect
121	    .poll(async () => {
122	      const ship = await readout(page, sessionId);
123	      return ship === undefined ? undefined : [ship.x, ship.y, ship.speed];
124	    })
125	    .toEqual([tileX * TILE + TILE / 2, tileY * TILE + TILE / 2, 0]);
126	}
127	
128	/**
129	 * Test-only (with the test placement setting, as here): the next match created runs with these timings, in world
130	 * ticks, on top of the browser server's own; later matches keep the server's.
131	 */
132	export async function nextMatchTimings(request: APIRequestContext, timings: TestTimings): Promise<void> {
133	  const response = await request.post(`${SERVER_URL}${TEST_NEXT_MATCH_TIMINGS_PATH}`, { data: timings });
134	  expect(response.status(), await response.text()).toBe(200);
135	}
136	
137	/** Canvas pixels as RGBA rows, read from a real screenshot of the canvas. */
138	async function canvasPixels(page: Page, points: readonly { x: number; y: number }[], radius: number): Promise<[number, number, number][][]> {
139	  const png = await page.locator("#game canvas").screenshot();
140	  return page.evaluate(
141	    async ({ base64, points, radius }) => {
142	      const blob = await (await fetch(`data:image/png;base64,${base64}`)).blob();
143	      const bitmap = await createImageBitmap(blob);
144	      const canvas = new OffscreenCanvas(bitmap.width, bitmap.height);
145	      const context = canvas.getContext("2d")!;
146	      context.drawImage(bitmap, 0, 0);
147	      return points.map(({ x, y }) => {
148	        const pixels: [number, number, number][] = [];
149	        for (let dy = -radius; dy <= radius; dy++) {
150	          for (let dx = -radius; dx <= radius; dx++) {
151	            const px = x + dx;
152	            const py = y + dy;
153	            if (px < 0 || py < 0 || px >= bitmap.width || py >= bitmap.height) continue;
154	            const [r, g, b] = context.getImageData(px, py, 1, 1).data;
155	            pixels.push([r!, g!, b!]);
156	          }
157	        }
158	        return pixels;
159	      });
160	    },
161	    { base64: png.toString("base64"), points, radius },
162	  );
163	}
164	
165	function near(pixel: [number, number, number], color: string, tolerance = 24): boolean {
166	  const want = Number.parseInt(color.slice(1), 16);
167	  const [r, g, b] = pixel;
168	  return Math.abs(r - ((want >> 16) & 0xff)) <= tolerance && Math.abs(g - ((want >> 8) & 0xff)) <= tolerance && Math.abs(b - (want & 0xff)) <= tolerance;
169	}
170	
171	/**
172	 * The ids of ships whose colour is actually on the canvas where the scene says it drew them. Reads a real
173	 * screenshot of the canvas, so it checks rendered pixels rather than scene bookkeeping.
174	 */
175	export async function shipsOnCanvas(page: Page): Promise<string[]> {
176	  const drawn = await drawnShips(page);
177	  const pixels = await canvasPixels(page, drawn, 0);
178	  return drawn.filter((ship, index) => near(pixels[index]![0]!, ship.color)).map((ship) => ship.id).sort();
179	}
180	
181	/** The camera's scroll, in world pixels. */
182	export async function camera(page: Page): Promise<{ x: number; y: number }> {
183	  const [x, y] = ((await page.getByTestId("game").getAttribute("data-camera")) ?? "0,0").split(",").map(Number);
184	  return { x: x!, y: y! };
185	}
186	
187	/**
188	 * Whether a ship's colour shows anywhere within a few pixels of where a ship at world position (x, y) sub-units would
189	 * be drawn on this page's canvas.
190	 */
191	export async function colourAt(page: Page, x: number, y: number, color: string): Promise<boolean> {
192	  const scroll = await camera(page);
193	  const point = { x: Math.round(x * PIXELS_PER_SUB_UNIT - scroll.x), y: Math.round(y * PIXELS_PER_SUB_UNIT - scroll.y) };
194	  const [pixels] = await canvasPixels(page, [point], 4);
195	  return pixels!.some((pixel) => near(pixel, color));
196	}
197	
198	const hex = (color: number) => `#${color.toString(16).padStart(6, "0")}`;
199	
200	/**
201	 * The share, from 0 to 1, of a tile's pixels on this page's canvas within a few levels of a palette colour: its
202	 * interior, one pixel in from each edge, placed through the camera's scroll. Reads a real screenshot of the canvas, so it checks that the tile map
203	 * is drawn, not what the scene meant to draw.
204	 */
205	export async function tileColourShare(page: Page, tileX: number, tileY: number, color: number): Promise<number> {
206	  const scroll = await camera(page);
207	  const centre = { x: tileX * TILE_PIXELS + TILE_PIXELS / 2 - scroll.x, y: tileY * TILE_PIXELS + TILE_PIXELS / 2 - scroll.y };
208	  const [pixels] = await canvasPixels(page, [centre], TILE_PIXELS / 2 - 1);
209	  return pixels!.filter((pixel) => near(pixel, hex(color))).length / pixels!.length;
210	}
211	
212	/**
213	 * For each tile, whether the minimap pixel over its centre is within a few levels of a palette colour. The scene
214	 * reports where it put the minimap (`data-minimap`: left, top, scale); the pixels come from a real screenshot.
215	 */
216	export async function minimapShows(page: Page, tiles: readonly { tileX: number; tileY: number }[], color: number): Promise<boolean[]> {
217	  const [left, top, scale] = ((await page.getByTestId("game").getAttribute("data-minimap")) ?? "").split(",").map(Number);
218	  const points = tiles.map(({ tileX, tileY }) => ({ x: Math.floor(left! + (tileX + 0.5) * scale!), y: Math.floor(top! + (tileY + 0.5) * scale!) }));
219	  const pixels = await canvasPixels(page, points, 0);
220	  return pixels.map(([pixel]) => near(pixel!, hex(color)));
221	}
222	
223	/** How many tiles the page's minimap fog has revealed so far. */
224	export async function fogRevealed(page: Page): Promise<number> {
225	  return Number((await page.getByTestId("game").getAttribute("data-fog-revealed")) ?? "0");
226	}
227	
228	/** Where the page drew its own ship this frame, in world sub-units, or undefined before it draws it. */
229	export async function ownDrawnPosition(page: Page): Promise<{ x: number; y: number } | undefined> {
230	  const id = await selfId(page);
231	  const own = (await drawnShips(page)).find((ship) => ship.id === id);
232	  if (own === undefined) return undefined;
233	  const scroll = await camera(page);
234	  return { x: (own.x + scroll.x) / PIXELS_PER_SUB_UNIT, y: (own.y + scroll.y) / PIXELS_PER_SUB_UNIT };
235	}
236	
237	/** The colour a page draws its own ship in. */
238	export async function ownColour(page: Page): Promise<string> {
239	  const id = await selfId(page);
240	  await expect.poll(async () => (await drawnShips(page)).some((ship) => ship.id === id)).toBe(true);
241	  return (await drawnShips(page)).find((ship) => ship.id === id)!.color;
242	}
243	
244	/**
245	 * Where a world position in sub-units falls on this page's canvas, whether that is inside the canvas, and how far it
246	 * is from the canvas's centre, in pixels on each axis.
247	 */
248	export async function onCanvas(page: Page, x: number, y: number): Promise<{ x: number; y: number; inside: boolean; offCentre: number }> {
249	  const scroll = await camera(page);
250	  const size = await page.locator("#game canvas").evaluate((canvas: HTMLCanvasElement) => ({ width: canvas.width, height: canvas.height }));
251	  const point = { x: x * PIXELS_PER_SUB_UNIT - scroll.x, y: y * PIXELS_PER_SUB_UNIT - scroll.y };
252	  return {
253	    ...point,
254	    inside: point.x >= 0 && point.y >= 0 && point.x < size.width && point.y < size.height,
255	    offCentre: Math.max(Math.abs(point.x - size.width / 2), Math.abs(point.y - size.height / 2)),
256	  };
257	}
258	
259	/** Whether a ship's hull (a square of `hullHalfSize`) at a position in sub-units overlaps only navigable tiles. */
260	function hullClear(x: number, y: number): boolean {
261	  const half = shipTuning.hullHalfSize;
262	  for (let row = Math.floor((y - half) / TILE); row <= Math.floor((y + half) / TILE); row++) {
263	    for (let column = Math.floor((x - half) / TILE); column <= Math.floor((x + half) / TILE); column++) {
264	      if (!isNavigable(seaMap, column, row)) return false;
265	    }
266	  }
267	  return true;
268	}
269	
270	/**
271	 * Whether the straight line between two positions, in sub-units, is open sea for the whole width of a hull. `sailTo`
272	 * steers straight at its target, so every leg of a test's course must be one. Checked one sub-unit at a time along the
273	 * longer axis, as the simulation checks a mooring run, so no tile corner slips between two checks.
274	 */
275	export function clearCourse(from: { x: number; y: number }, to: { x: number; y: number }): boolean {
276	  const steps = Math.max(Math.abs(to.x - from.x), Math.abs(to.y - from.y), 1);
277	  for (let index = 0; index <= steps; index++) {
278	    const x = from.x + Math.trunc(((to.x - from.x) * index) / steps);
279	    const y = from.y + Math.trunc(((to.y - from.y) * index) / steps);
280	    if (!hullClear(x, y)) return false;
281	  }
282	  return true;
283	}
284	
285	export interface SailOptions {
286	  /** Stop once the ship has come to rest this close to the target, in sub-units. */
287	  readonly within?: number;
288	  /** Or once this holds. */
289	  readonly until?: () => Promise<boolean>;
290	  readonly timeoutMs?: number;
291	  /** Called with every readout on the way, for checks along the route. */
292	  readonly onReadout?: (ship: Readout) => void;
293	}
294	
295	/** One world step, in milliseconds: while a key is held the ship turns one heading unit, or speeds up once, per step. */
296	const STEP_MS = 1000 / WORLD_STEPS_PER_SECOND;
297	
298	/** The signed number of heading units from one heading to another, the short way round. */
299	function headingOff(from: number, to: number): number {
300	  return ((((to - from) % HEADING_COUNT) + HEADING_COUNT + HEADING_COUNT / 2) % HEADING_COUNT) - HEADING_COUNT / 2;
301	}
302	
303	/** Reads the page's own ship until two readouts two world steps apart show the same heading: it is not turning. */
304	async function steadyReadout(page: Page, id: string): Promise<Readout> {
305	  let ship = (await readout(page, id))!;
306	  for (;;) {
307	    await page.waitForTimeout(2 * STEP_MS);
308	    const again = (await readout(page, id))!;
309	    if (again.heading === ship.heading) return again;
310	    ship = again;
311	  }
312	}
313	
314	/**
315	 * A page's helm keys held for a number of world steps. A hold carries on for a while after the test lets go (the page
316	 * reads its keys on a timer, and a busy machine delays both), so each turn measures how far past its mark it went and
317	 * shortens the next holds by that much, or lengthens them when a hold fell short.
318	 */
319	class TimedHelm {
320	  /** How many world steps a hold carries on past its end, as measured so far. */
321	  private lag = 2;
322	
323	  constructor(
324	    private readonly page: Page,
325	    private readonly id: string,
326	  ) {}
327	
328	  async hold(key: string, steps: number): Promise<void> {
329	    await this.page.keyboard.down(key);
330	    await this.page.waitForTimeout(Math.max(0, steps - this.lag) * STEP_MS);
331	    await this.page.keyboard.up(key);
332	  }
333	
334	  /** Turns `off` heading units (positive to starboard) from `ship` at rest, and returns the ship once steady. */
335	  async turn(ship: Readout, off: number): Promise<Readout> {
336	    await this.hold(off > 0 ? "ArrowRight" : "ArrowLeft", Math.abs(off));
337	    const after = await steadyReadout(this.page, this.id);
338	    const turned = headingOff(ship.heading, after.heading) * Math.sign(off);
339	    this.lag = Math.min(8, Math.max(0, this.lag + (turned - Math.abs(off)) / 2));
340	    return after;
341	  }
342	}
343	
344	/**
345	 * How far a ship at rest goes, in sub-units, with ahead held for `steps` world steps and then released: it speeds up
346	 * by `acceleration` a step to at most `maxSpeed`, then coasts to a stop, losing `drag` a step.
347	 */
348	export function hopDistance(steps: number): number {
349	  let speed = 0;
350	  let distance = 0;
351	  for (let step = 0; step < steps; step++) distance += speed = Math.min(speed + shipTuning.acceleration, shipTuning.maxSpeed);
352	  while (speed > 0) distance += speed = Math.max(speed - shipTuning.drag, 0);
353	  return distance;
354	}
355	
356	/**
357	 * Sails a page's ship toward a world position with the keyboard only, from the HUD's authoritative readout, in hops:
358	 * with the ship at rest it turns to the bearing (left or right, held for as many world steps as it is off course),
359	 * then holds ahead for as many world steps as carry it about the rest of the way (from `shipTuning`'s acceleration,
360	 * top speed and drag), lets go and waits for it to coast to a stop. Nothing depends on reading the HUD in time: the
361	 * readout lags the server, more so on a busy machine, and steering on it continuously carries a ship past its course.
362	 * It never brakes, so it never reverses.
363	 */
364	export async function sailTo(page: Page, target: { x: number; y: number }, options: SailOptions = {}): Promise<Readout> {
365	  const id = await selfId(page);
366	  const helm = new TimedHelm(page, id);
367	  const deadline = Date.now() + (options.timeoutMs ?? 60_000);
368	  for (;;) {
369	    const ship = await readout(page, id);
370	    if (ship === undefined) throw new Error("own ship missing from the HUD");
371	    options.onReadout?.(ship);
372	    const dx = target.x - ship.x;
373	    const dy = target.y - ship.y;
374	    const distance = Math.hypot(dx, dy);
375	    if (options.until !== undefined && (await options.until())) return ship;
376	    if (ship.speed === 0 && options.within !== undefined && distance <= options.within) return ship;
377	    if (Date.now() > deadline) throw new Error(`did not reach ${target.x},${target.y} (at ${ship.x},${ship.y})`);
378	    if (ship.speed !== 0) {
379	      await page.waitForTimeout(2 * STEP_MS);
380	      continue;
381	    }
382	    const bearing = Math.round((Math.atan2(dy, dx) / (2 * Math.PI)) * HEADING_COUNT);
383	    const turn = headingOff(ship.heading, bearing);
384	    if (Math.abs(turn) > 1) {
385	      const turned = await helm.turn(ship, turn);
386	      options.onReadout?.(turned);
387	      continue;
388	    }
389	    let steps = 1;
390	    while (hopDistance(steps + 1) <= distance) steps++;
391	    await helm.hold("ArrowUp", steps);
392	    await page.waitForTimeout(2 * STEP_MS);
393	  }
394	}
395	
396	/**
397	 * Turns a page's ship at rest to one of a few headings with the keyboard, from the HUD's readout: holds left or right
398	 * for about as many world steps as it is off (the ship turns a heading unit a step), waits for the readout to show the
399	 * heading steady, and tries again until it is one of them.
400	 */
401	export async function turnTo(page: Page, headings: readonly number[], timeoutMs = 60_000): Promise<Readout> {
402	  const id = await selfId(page);
403	  const helm = new TimedHelm(page, id);
404	  const deadline = Date.now() + timeoutMs;
405	  let ship = await steadyReadout(page, id);
406	  for (;;) {
407	    if (headings.includes(ship.heading)) return ship;
408	    if (Date.now() > deadline) throw new Error(`did not turn to heading ${headings.join(" or ")} (at ${ship.heading})`);
409	    const [off] = headings.map((heading) => headingOff(ship.heading, heading)).sort((a, b) => Math.abs(a) - Math.abs(b));
410	    ship = await helm.turn(ship, off!);
411	  }
412	}
413	
414	/**
415	 * Records every text the page's dock hint shows from now on, as a player would read it; `dockHintsSeen` returns them.
416	 * A MutationObserver catches a hint that is shown only briefly.
417	 */
418	export async function recordDockHints(page: Page): Promise<void> {
419	  await page.evaluate(() => {
420	    const hint = document.querySelector('[data-testid="hud-dock-hint"]')!;
421	    const seen: string[] = [hint.textContent ?? ""];
422	    (window as unknown as { __dockHints: string[] }).__dockHints = seen;
423	    new MutationObserver(() => seen.push(hint.textContent ?? "")).observe(hint, { childList: true, characterData: true, subtree: true });
424	  });
425	}
426	
427	export async function dockHintsSeen(page: Page): Promise<string[]> {
428	  return page.evaluate(() => (window as unknown as { __dockHints: string[] }).__dockHints);
429	}
430	
431	/** Attaches the one screenshot a scenario's verifier reads. */
432	export async function attachScreenshot(page: Page, testInfo: TestInfo, scenario: string): Promise<void> {
433	  const path = testInfo.outputPath(`${scenario}.png`);
434	  await page.screenshot({ path });
435	  await testInfo.attach(`screenshot:${scenario}`, { path, contentType: "image/png" });
436	}
