1633	  /**
1634	   * Each client's view (§3, §6, §12, §16): its own ship unless it waits to respawn, the ships it can see that are not
1635	   * in a duel or waiting to respawn, the grapples whose attacker it sees or that aim at it (with the target blanked
1636	   * unless it sees the target too), the duel markers and caches in its sight, its own status and its own duel. A
1637	   * fighter or a player waiting to respawn sees no other ship, grapple, marker or cache. Nothing else is encoded for it.
1638	   */
1639	  private updateViews(): void {
1640	    const inDuel = new Set(this.encounters.duels.flatMap((duel) => duel.players));
1641	    const respawning = new Set(this.encounters.players.filter((player) => player.respawn !== null).map((player) => player.id));
1642	    const ships = new Map(this.simulation.ships.map((ship) => [ship.id, ship]));
1643	    for (const client of this.clients) {
1644	      const view = client.view;
1645	      if (view === undefined) continue;
1646	      const self = client.sessionId;
1647	      const viewer = ships.get(self);
1648	      const away = inDuel.has(self) || respawning.has(self);
1649	      const sync = (item: Parameters<typeof view.add>[0], visible: boolean) => {
1650	        const shown = view.has(item);
1651	        if (visible && !shown) view.add(item);
1652	        else if (!visible && shown) view.remove(item);
1653	      };
1654	      const visible = visibleShipIds(this.config, this.simulation, self);
1655	      for (const [id, ship] of this.state.ships) {
1656	        sync(ship, id === self ? !respawning.has(id) : visible.has(id) && !away && !inDuel.has(id) && !respawning.has(id));
1657	      }
1658	      const sees = (id: string) => {
1659	        const other = ships.get(id);
1660	        return !away && viewer !== undefined && other !== undefined && canSee(this.config, viewer, other);
1661	      };
1662	      for (const attempt of this.encounters.attempts) {
1663	        const aimedAt = attempt.attackerId === self || attempt.defenderId === self;
1664	        const full = aimedAt || (sees(attempt.attackerId) && sees(attempt.defenderId));
